1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/url"
10		"sort"
11		"strings"
12	)
13	
14	// Route is one configured route: an id, accepted methods, a path prefix and
15	// the upstream URL requests on that route are forwarded to. An optional
16	// queryTransforms list rewrites the request query string after the route has
17	// been selected.
18	type Route struct {
19		ID              string            `json:"id"`
20		Methods         []string          `json:"methods"`
21		PathPrefix      string            `json:"pathPrefix"`
22		Upstream        string            `json:"upstream"`
23		QueryTransforms []*QueryTransform `json:"-"`
24	
25		// queryTransformsRaw holds the undecoded queryTransforms value until
26		// Config.UnmarshalJSON validates it once the route's position in its own
27		// config is known.
28		queryTransformsRaw json.RawMessage
29	}
30	
31	// QueryTransform is one rule in a route's queryTransforms array: op is
32	// "set", "remove" or "rename"; name is matched against decoded parameter
33	// names, value (set only) is used literally, and to (rename only) is the
34	// literal replacement name.
35	type QueryTransform struct {
36		Op    string `json:"op"`
37		Name  string `json:"name"`
38		Value string `json:"value"`
39		To    string `json:"to"`
40	}
41	
42	// routeJSON mirrors Route but keeps every field raw: the basic fields are
43	// type-checked in Config.UnmarshalJSON with the route's position (and, when
44	// available, its id), so a wrong field type is reported on that route rather
45	// than as a generic JSON decode error, and queryTransforms can surface
46	// null, wrong types and malformed rules the same way.
47	type routeJSON struct {
48		ID              json.RawMessage `json:"id"`
49		Methods         json.RawMessage `json:"methods"`
50		PathPrefix      json.RawMessage `json:"pathPrefix"`
51		Upstream        json.RawMessage `json:"upstream"`
52		QueryTransforms json.RawMessage `json:"queryTransforms"`
53	}
54	
55	// decodeRoute type-checks and decodes one raw route object. loc is the
56	// route's 1-based location in its config (e.g. "route 2"). The element's JSON
57	// type is checked first: a null entry or any non-object value fails on the
58	// entry itself, naming the position, the required object type and the type
59	// actually received, instead of falling through to a missing-field error such
60	// as a missing id. Field type errors then carry that location and, when the
61	// route supplies a valid non-empty string id anywhere in its object (even
62	// after the offending field), that id. Missing fields stay silent here and
63	// are rejected later by validate, which preserves the existing missing-field
64	// behavior.
65	func decodeRoute(data []byte, loc string) (Route, *Failure) {
66		elem := bytes.TrimSpace(data)
67		if len(elem) == 0 || elem[0] != '{' {
68			return Route{}, failuref("invalid_config",
69				"%s: route entry must be an object, got %s", loc, jsonTypeName(elem))
70		}
71		var rj routeJSON
72		if err := json.Unmarshal(elem, &rj); err != nil {
73			// The element already parsed as one JSON value and starts with '{';
74			// an object that cannot be read is a syntax failure rather than a
75			// field type error.
76			return Route{}, failuref("invalid_config", "config is not valid JSON: %v", err)
77		}
78	
79		var route Route
80		// Type-check id first so it can identify the route on an error in any
81		// later field regardless of object order. Only a valid non-empty JSON
82		// string becomes the label; a wrong-typed id is reported against the id
83		// field and never rendered (e.g. as a number or object) as the route's
84		// identity.
85		if f := decodeStringField(rj.ID, loc, "id", &route.ID); f != nil {
86			return Route{}, f
87		}
88		label := loc
89		if route.ID != "" {
90			label = routeLabel(loc, route.ID)
91		}
92	
93		if f := decodeMethodsField(rj.Methods, label, &route.Methods); f != nil {
94			return Route{}, f
95		}
96		if f := decodeStringField(rj.PathPrefix, label, "pathPrefix", &route.PathPrefix); f != nil {
97			return Route{}, f
98		}
99		if f := decodeStringField(rj.Upstream, label, "upstream", &route.Upstream); f != nil {
100			return Route{}, f
101		}
102		route.queryTransformsRaw = rj.QueryTransforms
103		return route, nil
104	}
105	
106	// decodeStringField type-checks a raw route field that must hold a string.
107	// An absent field is left as the zero value for later required-field
108	// validation; null or any non-string JSON value fails here.
109	func decodeStringField(raw json.RawMessage, label, field string, dst *string) *Failure {
110		if len(raw) == 0 {
111			return nil
112		}
113		if !jsonString(raw, dst) {
114			return failuref("invalid_config", "%s: %s must be a string", label, field)
115		}
116		return nil
117	}
118	
119	// decodeMethodsField type-checks methods: it must be an array of strings
120	// when present. An absent field is left nil for later required-field
121	// validation; null or any non-array value fails the field, and a number,
122	// boolean, object or null entry fails with the offending entry's position.
123	func decodeMethodsField(raw json.RawMessage, label string, dst *[]string) *Failure {
124		if len(raw) == 0 {
125			return nil
126		}
127		body := bytes.TrimSpace(raw)
128		if string(body) == "null" || len(body) == 0 || body[0] != '[' {
129			return failuref("invalid_config", "%s: methods must be an array of strings", label)
130		}
131		var elems []json.RawMessage
132		if err := json.Unmarshal(body, &elems); err != nil {
133			return failuref("invalid_config", "%s: methods must be an array of strings", label)
134		}
135		methods := make([]string, 0, len(elems))
136		for i, elem := range elems {
137			var m string
138			if !jsonString(bytes.TrimSpace(elem), &m) {
139				return failuref("invalid_config", "%s: methods entry %d must be a string", label, i+1)
140			}
141			methods = append(methods, m)
142		}
143		*dst = methods
144		return nil
145	}
146	
147	// parseQueryTransforms decodes and validates the raw queryTransforms array
148	// of one route. loc identifies the route; rule errors additionally carry a
149	// 1-based rule index.
150	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
151		body := strings.TrimSpace(string(raw))
152		if body == "null" {
153			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
154		}
155		var elems []json.RawMessage
156		if err := json.Unmarshal([]byte(body), &elems); err != nil {
157			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
158		}
159		transforms := make([]*QueryTransform, 0, len(elems))
160		for i, elem := range elems {
161			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
162			if string(bytes.TrimSpace(elem)) == "null" {
163				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
164			}
165			var fields map[string]json.RawMessage
166			if err := json.Unmarshal(elem, &fields); err != nil {
167				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
168			}
169	
170			qt := &QueryTransform{}
171			opRaw, ok := fields["op"]
172			switch {
173			case !ok:
174				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
175			case !jsonString(opRaw, &qt.Op):
176				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
177			case qt.Op != "set" && qt.Op != "remove" && qt.Op != "rename":
178				return nil, failuref("invalid_config", "%s: unknown op %q (only set, remove and rename are supported)", ruleLoc, qt.Op)
179			}
180	
181			nameRaw, ok := fields["name"]
182			switch {
183			case !ok:
184				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
185			case !jsonString(nameRaw, &qt.Name):
186				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
187			case qt.Name == "":
188				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
189			}
190	
191			valueRaw, hasValue := fields["value"]
192			toRaw, hasTo := fields["to"]
193			switch qt.Op {
194			case "set":
195				if !hasValue {
196					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
197				}
198				if !jsonString(valueRaw, &qt.Value) {
199					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
200				}
201			case "remove":
202				if hasValue {
203					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
204				}
205			case "rename":
206				if hasValue {
207					return nil, failuref("invalid_config", "%s: rename must not include a value", ruleLoc)
208				}
209				switch {
210				case !hasTo:
211					return nil, failuref("invalid_config", "%s: rename requires a non-empty string to", ruleLoc)
212				case !jsonString(toRaw, &qt.To):
213					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
214				case qt.To == "":
215					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
216				}
217			}
218			transforms = append(transforms, qt)
219		}
220		return transforms, nil
221	}
222	
223	// jsonString decodes raw into s and reports whether raw is a JSON string
224	// (null, numbers, objects and arrays fail).
225	func jsonString(raw json.RawMessage, s *string) bool {
226		if len(raw) == 0 || raw[0] != '"' {
227			return false
228		}
229		return json.Unmarshal(raw, s) == nil
230	}
231	
232	// routeLabel renders the human-readable route location, adding the id when
233	// the configuration supplied one.
234	func routeLabel(loc, id string) string {
235		if id != "" {
236			return fmt.Sprintf("%s (id %q)", loc, id)
237		}
238		return loc
239	}
240	
241	// Config is the resolve configuration: a flat array of routes.
242	type Config struct {
243		Routes []Route `json:"routes"`
244	}
245	
246	// UnmarshalJSON first confirms the document is one syntactically valid JSON
247	// value, then checks its structure: the top-level value must be a JSON object
248	// and, when present, the routes field must hold an array. A syntactically
249	// legal value of the wrong shape (an array, string, number, boolean or null
250	// at the top level; a non-array routes, null included) is an invalid_config
251	// naming both the required type and the type received, never a JSON parse
252	// failure. The routes array is then decoded one entry at a time, each entry
253	// type-checked and validated against its 1-based position in this config; a
254	// non-object entry (null included) fails on that entry before any field is
255	// inspected. Decoding entries from raw values means wrong field types are
256	// reported on the offending route (with its id when available) instead of
257	// as a generic JSON syntax failure. The position comes from the array
258	// decoded here, so configs parsed concurrently or interleaved in the same
259	// process cannot shift each other's route numbering. A broken JSON document
260	// still fails the outer decode and is reported as a parse failure, without a
261	// guessed route position or field.
262	func (cfg *Config) UnmarshalJSON(data []byte) error {
263		// First confirm the document is one syntactically valid JSON value: only
264		// then is a wrong shape a structural error rather than a parse failure.
265		// This mirrors ParseRequest: broken syntax (including an empty file and a
266		// corrupt first route) stays a parse error with no guessed position.
267		var doc json.RawMessage
268		if err := json.Unmarshal(data, &doc); err != nil {
269			return err
270		}
271		body := bytes.TrimSpace(doc)
272		if body[0] != '{' {
273			return failuref("invalid_config", "config must be a JSON object, got %s", jsonTypeName(body))
274		}
275		var fields map[string]json.RawMessage
276		if err := json.Unmarshal(body, &fields); err != nil {
277			return err
278		}
279	
280		var rawRoutes []json.RawMessage
281		if raw, ok := fields["routes"]; ok {
282			body := bytes.TrimSpace(raw)
283			if len(body) == 0 || body[0] != '[' {
284				// null is a type error here, never an absent field: a config
285				// that explicitly supplies routes must supply an array.
286				return failuref("invalid_config", "routes must be an array, got %s", jsonTypeName(body))
287			}
288			if err := json.Unmarshal(body, &rawRoutes); err != nil {
289				return err
290			}
291		}
292	
293		// Pass 1: decode and type-check every entry, so a wrong field type on a
294		// later route fails before any queryTransforms validation (matching the
295		// precedence of decoding before validation).
296		cfg.Routes = make([]Route, len(rawRoutes))
297		for i, entry := range rawRoutes {
298			route, f := decodeRoute(entry, fmt.Sprintf("route %d", i+1))
299			if f != nil {
300				return f
301			}
302			cfg.Routes[i] = route
303		}
304		// Pass 2: validate each route's queryTransforms now that every position
305		// is known.
306		for i := range cfg.Routes {
307			route := &cfg.Routes[i]
308			if len(route.queryTransformsRaw) == 0 {
309				continue // field absent
310			}
311			loc := fmt.Sprintf("route %d", i+1)
312			transforms, f := parseQueryTransforms(route.queryTransformsRaw, loc, route.ID)
313			if f != nil {
314				return f
315			}
316			route.QueryTransforms = transforms
317			route.queryTransformsRaw = nil
318		}
319		return nil
320	}
321	
322	// Request is one resolution request: an HTTP method and a request target
323	// (path with an optional raw query string).
324	type Request struct {
325		Method string `json:"method"`
326		Target string `json:"target"`
327	}
328	
329	// Resolution is the successful result of matching a request.
330	type Resolution struct {
331		RouteID     string `json:"routeId"`
332		UpstreamURL string `json:"upstreamURL"`
333	}
334	
335	// Failure carries a stable machine-readable code and a human-readable reason.
336	type Failure struct {
337		Code       string   `json:"code"`
338		Reason     string   `json:"reason"`
339		Candidates []string `json:"candidates,omitempty"`
340	}
341	
342	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
343	
344	func failuref(code, format string, args ...any) *Failure {
345		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
346	}
347	
348	// ParseConfig parses and fully validates the route configuration.
349	func ParseConfig(data []byte) (*Config, *Failure) {
350		var cfg Config
351		if err := json.Unmarshal(data, &cfg); err != nil {
352			if f, ok := err.(*Failure); ok {
353				return nil, f
354			}
355			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
356		}
357		if f := cfg.validate(); f != nil {
358			return nil, f
359		}
360		return &cfg, nil
361	}
362	
363	func (cfg *Config) validate() *Failure {
364		seenIDs := make(map[string]int, len(cfg.Routes))
365		for i := range cfg.Routes {
366			route := &cfg.Routes[i]
367			loc := fmt.Sprintf("route %d", i+1)
368			if route.ID == "" {
369				return failuref("invalid_config", "%s: id must be non-empty", loc)
370			}
371			if first, ok := seenIDs[route.ID]; ok {
372				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
373			}
374			seenIDs[route.ID] = i + 1
375	
376			if len(route.Methods) == 0 {
377				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
378			}
379			for _, method := range route.Methods {
380				switch {
381				case method == "":
382					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
383				case method == "*":
384					// Wildcard matching any legal method.
385				case !isToken(method):
386					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
387				}
388			}
389	
390			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
391				return f
392			}
393			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
394				return f
395			}
396		}
397		return nil
398	}
399	
400	func validatePrefix(prefix, loc, id string) *Failure {
401		switch {
402		case prefix == "" || prefix[0] != '/':
403			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
404		case prefix != "/" && strings.HasSuffix(prefix, "/"):
405			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
406		case strings.ContainsAny(prefix, "?#"):
407			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
408		case !validPercentEscapes(prefix):
409			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
410		}
411		return nil
412	}
413	
414	func validateUpstream(raw, loc, id string) *Failure {
415		if strings.ContainsAny(raw, "?#") {
416			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
417		}
418		u, err := url.Parse(raw)
419		if err != nil {
420			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
421		}
422		if u.Scheme != "http" && u.Scheme != "https" {
423			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
424		}
425		if u.Host == "" {
426			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
427		}
428		return nil
429	}
430	
431	// requestJSON mirrors Request but keeps method and target raw, so a valid
432	// JSON document whose fields merely have the wrong JSON type is reported on
433	// the offending field instead of as a generic JSON decode error.
434	type requestJSON struct {
435		Method json.RawMessage `json:"method"`
436		Target json.RawMessage `json:"target"`
437	}
438	
439	// ParseRequest parses and validates one JSON request. Three failure shapes are
440	// kept apart: a document whose JSON syntax is broken fails as a parse failure
441	// without guessing a field; a syntactically valid non-object document (array,
442	// number, string, boolean or null) must be a JSON object; a valid object whose
443	// method or target is not a string fails on that field, naming the JSON type
444	// actually received (null counts as a type error, never as a missing field).
445	// method is always checked before target, regardless of the key order in the
446	// object. Only after both fields are present strings are their contents
447	// (required method, legal token, absolute target without a fragment or a bad
448	// percent escape) validated, so an empty string stays a content error.
449	func ParseRequest(data []byte) (*Request, *Failure) {
450		var doc json.RawMessage
451		if err := json.Unmarshal(data, &doc); err != nil {
452			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
453		}
454		body := bytes.TrimSpace(doc)
455		if len(body) == 0 || body[0] != '{' {
456			return nil, failuref("invalid_request", "request must be a JSON object")
457		}
458	
459		var rj requestJSON
460		if err := json.Unmarshal(body, &rj); err != nil {
461			// The document already parsed as one JSON value and starts with '{';
462			// keep this as a parse failure rather than a field error if the object
463			// itself cannot be read.
464			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
465		}
466	
467		var req Request
468		if f := decodeRequestStringField(rj.Method, "method", &req.Method); f != nil {
469			return nil, f
470		}
471		if f := decodeRequestStringField(rj.Target, "target", &req.Target); f != nil {
472			return nil, f
473		}
474	
475		switch {
476		case req.Method == "":
477			return nil, failuref("invalid_request", "method is required")
478		case !isToken(req.Method):
479			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
480		}
481		switch {
482		case req.Target == "" || req.Target[0] != '/':
483			return nil, failuref("invalid_request", "target must start with /")
484		case strings.Contains(req.Target, "#"):
485			return nil, failuref("invalid_request", "target must not contain a fragment")
486		case !validPercentEscapes(req.Target):
487			return nil, failuref("invalid_request", "target contains an invalid percent escape")
488		}
489		return &req, nil
490	}
491	
492	// decodeRequestStringField type-checks one request field that must hold a
493	// string. An absent field (no such key) is left as the zero value so the
494	// later content checks keep their "field is required" behavior; null or any
495	// non-string JSON value is a type error that names the field and the JSON
496	// type that was actually supplied.
497	func decodeRequestStringField(raw json.RawMessage, field string, dst *string) *Failure {
498		if len(raw) == 0 {
499			return nil
500		}
501		if jsonString(raw, dst) {
502			return nil
503		}
504		return failuref("invalid_request", "%s must be a string, got %s", field, jsonTypeName(raw))
505	}
506	
507	// jsonTypeName names the JSON type of a syntactically valid raw value, in the
508	// terms the request error reasons use: "null", "a boolean", "a number",
509	// "a string", "an array" or "an object".
510	func jsonTypeName(raw json.RawMessage) string {
511		switch bytes.TrimSpace(raw)[0] {
512		case 'n':
513			return "null"
514		case 't', 'f':
515			return "a boolean"
516		case '"':
517			return "a string"
518		case '[':
519			return "an array"
520		case '{':
521			return "an object"
522		default:
523			return "a number"
524		}
525	}
526	
527	// Resolve matches a validated request against a validated configuration and
528	// computes the upstream URL. Failure codes are route_not_found and
529	// route_conflict.
530	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
531		path := req.Target
532		if i := strings.IndexByte(path, '?'); i >= 0 {
533			path = path[:i]
534		}
535	
536		type candidate struct {
537			route    *Route
538			concrete bool
539		}
540		var matched []candidate
541		for i := range cfg.Routes {
542			route := &cfg.Routes[i]
543			concrete, wildcard := methodMatch(route.Methods, req.Method)
544			if !concrete && !wildcard {
545				continue
546			}
547			if !prefixMatch(route.PathPrefix, path) {
548				continue
549			}
550			matched = append(matched, candidate{route, concrete})
551		}
552		if len(matched) == 0 {
553			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
554		}
555	
556		// Longest prefix wins.
557		bestLen := 0
558		for _, c := range matched {
559			if n := len(c.route.PathPrefix); n > bestLen {
560				bestLen = n
561			}
562		}
563		winners := matched[:0]
564		for _, c := range matched {
565			if len(c.route.PathPrefix) == bestLen {
566				winners = append(winners, c)
567			}
568		}
569	
570		// Among equal prefixes a concrete method beats the wildcard.
571		var concrete []candidate
572		for _, c := range winners {
573			if c.concrete {
574				concrete = append(concrete, c)
575			}
576		}
577		if len(concrete) > 0 {
578			winners = concrete
579		}
580		if len(winners) > 1 {
581			ids := make([]string, 0, len(winners))
582			for _, c := range winners {
583				ids = append(ids, c.route.ID)
584			}
585			sort.Strings(ids)
586			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
587			f.Candidates = ids
588			return nil, f
589		}
590	
591		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
592		if f != nil {
593			return nil, f
594		}
595		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
596	}
597	
598	// methodMatch reports whether the method list matches the request method
599	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
600	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
601		for _, m := range methods {
602			switch {
603			case m == "*":
604				wildcard = true
605			case m == method:
606				concrete = true
607			}
608		}
609		return concrete, wildcard
610	}
611	
612	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
613	// treated as a separator and the root prefix matches every origin-path.
614	func prefixMatch(prefix, path string) bool {
615		if prefix == "/" {
616			return true
617		}
618		if path == prefix {
619			return true
620		}
621		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
622	}
623	
624	// joinUpstream strips the route prefix from the request path and joins the
625	// remainder onto the upstream base path with exactly one slash at the
626	// junction. The junction is one run of literal slashes: every trailing
627	// slash on the base path and every leading slash on the remainder are
628	// merged into that single slash, even when either side contributes
629	// several. Nothing else is normalized: slashes inside either part, the
630	// remainder's trailing slashes (once non-slash content has appeared),
631	// ".", ".." and percent escapes such as "%2F" are carried over byte for
632	// byte, never decoded first. The base path is sliced out of the raw
633	// upstream so joining never re-encodes, reorders or drops anything
634	// outside the junction. The raw query is preserved verbatim unless the
635	// route defines queryTransforms, in which case they rewrite it after
636	// route selection.
637	func joinUpstream(route *Route, path, target string) (string, *Failure) {
638		if _, err := url.Parse(route.Upstream); err != nil {
639			// Config validation already rejected this.
640			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
641		}
642	
643		var remainder string
644		switch {
645		case route.PathPrefix == "/":
646			// Root keeps the whole following path; "/" itself has an empty remainder.
647			if path != "/" {
648				remainder = path
649			}
650		default:
651			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
652		}
653	
654		// Slice the validated upstream raw so nothing outside the junction is
655		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
656		schemeEnd := strings.Index(route.Upstream, "://")
657		tail := route.Upstream[schemeEnd+3:]
658		hostPart, basePath := tail, ""
659		if i := strings.IndexByte(tail, '/'); i >= 0 {
660			hostPart, basePath = tail[:i], tail[i:]
661		}
662	
663		// Collapse only the junction run: all trailing slashes of the base
664		// path meet all leading slashes of the remainder, and the junction
665		// keeps exactly one slash whether or not anything follows them. A
666		// remainder made entirely of slashes has no content past the run, so
667		// it likewise ends in that single slash.
668		baseTrimmed := strings.TrimRight(basePath, "/")
669		rest := strings.TrimLeft(remainder, "/")
670		joined := baseTrimmed + "/" + rest
671	
672		result := route.Upstream[:schemeEnd+3] + hostPart + joined
673		query, f := applyQueryTransforms(route.QueryTransforms, target)
674		if f != nil {
675			return "", f
676		}
677		return result + query, nil
678	}
679	
680	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
681	func isToken(s string) bool {
682		if s == "" {
683			return false
684		}
685		for i := 0; i < len(s); i++ {
686			if !isTokenChar(s[i]) {
687				return false
688			}
689		}
690		return true
691	}
692	
693	func isTokenChar(c byte) bool {
694		switch {
695		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
696			return true
697		}
698		switch c {
699		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
700			return true
701		}
702		return false
703	}
704	
705	// validPercentEscapes checks that every "%' is followed by two hex digits.
706	// Matching and joining stay on raw strings, but malformed escapes are rejected
707	// up front for both prefixes and request targets.
708	func validPercentEscapes(s string) bool {
709		for i := 0; i < len(s); i++ {
710			if s[i] != '%' {
711				continue
712			}
713			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
714				return false
715			}
716			i += 2
717		}
718		return true
719	}
720	
721	func isHex(c byte) bool {
722		switch {
723		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
724			return true
725		}
726		return false
727	}
728

