174				name:     "encoded slash right at the junction is data, not a junction slash",
175				request:  `{"method":"GET","target":"/api/%2f/x"}`,
176				routeID:  "multi",
177				upstream: "http://backend.internal/base/%2f/x",
178			},
179			{
180				name:     "plain base with doubled leading remainder slashes collapses too",
181				request:  `{"method":"GET","target":"/v//orders"}`,
182				routeID:  "plain",
183				upstream: "http://plain.internal/base/orders",
184			},
185			{
186				name:     "upstream without a base path still joins with one slash",
