280	func TestResolveConflict(t *testing.T) {
281		cfg := mustConfig(t, `{
282		  "routes": [
283		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://z.internal"},
284		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://a.internal"},
285		    {"id": "mid",   "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://m.internal"}
286		  ]
287		}`)
288		req, f := ParseRequest([]byte(`{"method":"GET","target":"/things"}`))
289		if f != nil {
290			t.Fatalf("unexpected request failure: %+v", f)
291		}
292		_, rf := Resolve(cfg, req)
293		if rf == nil {
294			t.Fatal("expected route_conflict")
295		}
296		if rf.Code != "route_conflict" {
297			t.Fatalf("code = %q, want route_conflict", rf.Code)
298		}
299		want := []string{"alpha", "mid", "zeta"}
300		if len(rf.Candidates) != len(want) {
301			t.Fatalf("candidates = %v, want %v", rf.Candidates, want)
302		}
303		for i := range want {
304			if rf.Candidates[i] != want[i] {
305				t.Fatalf("candidates = %v, want sorted %v", rf.Candidates, want)
306			}
307		}
308	
309		// Concrete vs wildcard at same prefix is NOT a conflict.
310		cfg2 := mustConfig(t, `{
311		  "routes": [
312		    {"id": "b-wild", "methods": ["*"],  "pathPrefix": "/things", "upstream": "http://w.internal"},
313		    {"id": "a-get",  "methods": ["GET"],"pathPrefix": "/things", "upstream": "http://g.internal"}
314		  ]
315		}`)
316		res := resolveJSON(t, cfg2, `{"method":"GET","target":"/things/x"}`)
317		if res.RouteID != "a-get" {
318			t.Fatalf("routeId = %q, want a-get", res.RouteID)
319		}
320	
321		// Two wildcards with no concrete entry remain a conflict.
322		cfg3 := mustConfig(t, `{
323		  "routes": [
324		    {"id": "w1", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w1.internal"},
325		    {"id": "w2", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w2.internal"}
326		  ]
327		}`)
328		_, rf = Resolve(cfg3, mustReq(t, "POST", "/things/x"))
329		if rf == nil || rf.Code != "route_conflict" {
330			t.Fatalf("got %+v, want route_conflict between wildcard routes", rf)
331		}
332	}
