334	// configFromRoutes builds a config document from raw route objects, so the
335	// same routes can be parsed in different orders.
336	func configFromRoutes(routes ...string) string {
337		return `{"routes":[` + strings.Join(routes, ",") + `]}`
338	}
339	
340	func reversed(routes []string) []string {
341		out := make([]string, len(routes))
342		for i, r := range routes {
343			out[len(routes)-1-i] = r
344		}
345		return out
346	}
