481	func TestResolveConflictOnlyAmongFinalCandidates(t *testing.T) {
482		// A conflict is reported only when the final candidates cannot be
483		// narrowed to one: shorter-prefix routes and same-prefix wildcard routes
484		// are already eliminated and must not appear in the candidate list, and
485		// no route may be returned as a success.
486		routes := []string{
487			`{"id":"z-short","methods":["GET"],"pathPrefix":"/a","upstream":"http://short.internal"}`,
488			`{"id":"wild-long","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal"}`,
489			`{"id":"zeta","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://z.internal"}`,
490			`{"id":"alpha","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://a.internal"}`,
491		}
492		for _, order := range [][]string{routes, reversed(routes)} {
493			cfg := mustConfig(t, configFromRoutes(order...))
494	
495			res, rf := Resolve(cfg, mustReq(t, "GET", "/a/b/x"))
496			if res != nil {
497				t.Fatalf("got success %+v, want route_conflict", res)
498			}
499			if rf == nil || rf.Code != "route_conflict" {
500				t.Fatalf("got %+v, want route_conflict", rf)
501			}
502			if want := []string{"alpha", "zeta"}; !equalStrings(rf.Candidates, want) {
503				t.Fatalf("candidates = %v, want %v (lexicographic, no shorter-prefix or wildcard routes)", rf.Candidates, want)
504			}
505	
506			// The wildcard route at the conflicted prefix still serves methods
507			// that have no concrete rival there.
508			res = resolveJSON(t, cfg, `{"method":"POST","target":"/a/b/x"}`)
509			if res.RouteID != "wild-long" {
510				t.Fatalf("POST: routeId = %q, want wild-long", res.RouteID)
511			}
512	
513			// The shorter-prefix route still serves requests that never reach
514			// the conflicted prefix.
515			res = resolveJSON(t, cfg, `{"method":"GET","target":"/a/other"}`)
516			if res.RouteID != "z-short" {
517				t.Fatalf("GET /a/other: routeId = %q, want z-short", res.RouteID)
518			}
519		}
520	}
