560	func TestInvalidConfig(t *testing.T) {
561		cases := []struct {
562			name    string
563			src     string
564			want    string // reason substring
565			located bool   // whether the reason should locate the route
566		}{
567			{"not json", `{not json`, "not valid JSON", false},
568			{"empty id", `{"routes":[{"id":"","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`, "id must be non-empty", true},
569			{"duplicate id", `{"routes":[
570			  {"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h1"},
571			  {"id":"x","methods":["GET"],"pathPrefix":"/b","upstream":"http://h2"}]}`, "duplicate id", true},
572			{"empty methods", `{"routes":[{"id":"x","methods":[],"pathPrefix":"/a","upstream":"http://h"}]}`, "non-empty", true},
573			{"bad method token", `{"routes":[{"id":"x","methods":["GE T"],"pathPrefix":"/a","upstream":"http://h"}]}`, "invalid method", true},
574			{"prefix not absolute", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"a","upstream":"http://h"}]}`, "start with /", true},
575			{"prefix trailing slash", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a/","upstream":"http://h"}]}`, "end with /", true},
576			{"root trailing slash allowed", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/","upstream":"http://h"}]}`, "", true},
577			{"prefix with query", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a?x=1","upstream":"http://h"}]}`, "query string or fragment", true},
578			{"prefix with fragment", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a#f","upstream":"http://h"}]}`, "query string or fragment", true},
579			{"prefix bad percent escape", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a%2","upstream":"http://h"}]}`, "percent escape", true},
580			{"upstream relative", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"/path"}]}`, "absolute http or https", true},
581			{"upstream wrong scheme", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"ftp://h"}]}`, "absolute http or https", true},
582			{"upstream missing host", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http:///path"}]}`, "include a host", true},
583			{"upstream with query", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h?x=1"}]}`, "query string or fragment", true},
584			{"upstream with fragment", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h#f"}]}`, "query string or fragment", true},
585		}
586		for _, tc := range cases {
587			t.Run(tc.name, func(t *testing.T) {
588				_, f := ParseConfig([]byte(tc.src))
589				if tc.want == "" {
590					if f != nil {
591						t.Fatalf("unexpected failure: %+v", f)
592					}
593					return
594				}
595				if f == nil {
596					t.Fatalf("expected invalid_config containing %q", tc.want)
597				}
598				if f.Code != "invalid_config" {
599					t.Fatalf("code = %q, want invalid_config", f.Code)
600				}
601				if !strings.Contains(f.Reason, tc.want) {
602					t.Fatalf("reason = %q, want substring %q", f.Reason, tc.want)
603				}
604				if tc.located && !strings.Contains(f.Reason, "route ") {
605					t.Fatalf("reason = %q should locate the route", f.Reason)
606				}
607			})
608		}
609	}
