706					t.Fatalf("code = %q, want invalid_config", f.Code)
707				}
708				if strings.Contains(f.Reason, "not valid JSON") {
709					t.Fatalf("field type error must not be described as a JSON syntax failure: %q", f.Reason)
710				}
711				for _, want := range tc.want {
712					if !strings.Contains(f.Reason, want) {
713						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
714					}
715				}
716				for _, bad := range tc.forbidden {
