725		// route position, even when the document opens with a routes field,
726		// contains a complete first route, or is corrupt inside the array.
727		for _, src := range []string{
728			`{not json`,
729			`{"routes": [{"id":"x"} broken`,
730			`{"routes":[ broken`,
731			`{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}] broken`,
732		} {
