538				request:   `{"method":null,"target":"/api"}`,
539				want:      []string{"method must be a string", "got null"},
540				forbidden: []string{"method is required"},
541			},
542			{
543				name:      "both fields wrong report method regardless of key order",
544				request:   `{"target":[],"method":42}`,
545				want:      []string{"method must be a string"},
