630				want:      []string{"config must be a JSON object", "got a string"},
631				forbidden: []string{"not valid JSON"},
632			},
633			{
634				name:      "routes null is a type error, not an empty config",
635				config:    `{"routes":null}`,
636				want:      []string{"routes must be an array", "got null"},
637				forbidden: []string{"not valid JSON"},
638			},
639			{
640				name:      "routes object",
641				config:    `{"routes":{}}`,
642				want:      []string{"routes must be an array", "got an object"},
643				forbidden: []string{"not valid JSON"},
644			},
645			{
646				name: "null element after a route the request would match",
647				config: `{
648				  "routes": [
649				    {"id": "api", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://api.internal/v1"},
650				    null
651				  ]
652				}`,
653				want:      []string{"route 2", "route entry must be an object", "got null"},
654				forbidden: []string{"not valid JSON", "id"},
655			},
656			{
657				name:      "boolean element as the only route",
658				config:    `{"routes":[true]}`,
659				want:      []string{"route 1", "route entry must be an object", "got a boolean"},
660				forbidden: []string{"not valid JSON", "id"},
661			},
662		}
663		for _, tc := range cases {
664			t.Run(tc.name, func(t *testing.T) {
665				res := runResolveCLI(t, tc.config, cliSuccessRequest)
666				if res.exitCode == 0 {
667					t.Fatalf("exit code = 0, want non-zero")
668				}
669				if len(res.stdout) != 0 {
670					t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
671				}
672				var fail struct {
673					Code   string `json:"code"`
674					Reason string `json:"reason"`
675				}
676				decodeOneJSON(t, res.stderr, "stderr", &fail)
677				if fail.Code != "invalid_config" {
678					t.Fatalf("code = %q, want invalid_config", fail.Code)
679				}
680				for _, want := range tc.want {
681					if !strings.Contains(fail.Reason, want) {
682						t.Errorf("reason = %q, want substring %q", fail.Reason, want)
683					}
684				}
685				for _, bad := range tc.forbidden {
686					if strings.Contains(fail.Reason, bad) {
687						t.Errorf("reason = %q must not contain %q", fail.Reason, bad)
688					}
689				}
690			})
691		}
692	
693		// A structurally wrong config is reported before the request is even
694		// examined, so routes:null paired with broken-JSON request still yields
695		// invalid_config.
696		res := runResolveCLI(t, `{"routes":null}`, `{not json`)
697		if res.exitCode == 0 || len(res.stdout) != 0 {
698			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
699		}
700		var fail struct {
701			Code   string `json:"code"`
702			Reason string `json:"reason"`
703		}
704		decodeOneJSON(t, res.stderr, "stderr", &fail)
705		if fail.Code != "invalid_config" {
706			t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
707		}
708		if !strings.Contains(fail.Reason, "routes must be an array") {
709			t.Fatalf("reason = %q, want the routes type error", fail.Reason)
710		}
711	
712		// A broken-JSON config is still a parse failure at the boundary, even
713		// though the fragment looks like it starts a routes array.
714		broken := runResolveCLI(t, `{"routes":[ broken`, cliSuccessRequest)
715		if broken.exitCode == 0 {
716			t.Fatal("broken config must exit non-zero")
717		}
718		var brokenFail struct {
719			Code   string `json:"code"`
720			Reason string `json:"reason"`
721		}
722		decodeOneJSON(t, broken.stderr, "stderr", &brokenFail)
723		if brokenFail.Code != "invalid_config" || !strings.Contains(brokenFail.Reason, "not valid JSON") {
724			t.Fatalf("got %+v, want invalid_config parse failure", brokenFail)
725		}
726	}
