728	func TestResolveCLIRouteConflict(t *testing.T) {
729		// alpha and zeta both concretely accept GET at the same /api prefix
730		// with no longer prefix to win; the same-prefix wildcard route must not
731		// appear among the final candidates.
732		config := `{
733		  "routes": [
734		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://z.internal/v1"},
735		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://a.internal/v1"},
736		    {"id": "wild",  "methods": ["*"],   "pathPrefix": "/api", "upstream": "http://w.internal/v1"}
737		  ]
738		}`
