package main

import (
	"fmt"
	"net/url"
	"strings"
)

func validPercentEscapes(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] != '%' {
			continue
		}
		if i+2 >= len(s) {
			return false
		}
		h := func(c byte) bool {
			return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
		}
		if !h(s[i+1]) || !h(s[i+2]) {
			return false
		}
		i += 2
	}
	return true
}

func main() {
	upstream := "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f///"
	u, err := url.Parse(upstream)
	fmt.Printf("parse err=%v scheme=%q host=%q\n", err, u.Scheme, u.Host)
	schemeEnd := strings.Index(upstream, "://")
	tail := upstream[schemeEnd+3:]
	hostPart, basePath := tail, ""
	if i := strings.IndexByte(tail, '/'); i >= 0 {
		hostPart, basePath = tail[:i], tail[i:]
	}
	fmt.Printf("hostPart=%q basePath=%q\n", hostPart, basePath)

	// illegal escape in upstream path
	bad := "http://h.internal/base%zz"
	u2, err2 := url.Parse(bad)
	fmt.Printf("bad parse err=%v u=%+v\n", err2, u2)
	fmt.Printf("validPercentEscapes(bad path)=%v\n", validPercentEscapes("/base%zz"))
}
EOF
